{
  "analysis": "kappa_diversity_vs_keff_regression",
  "purpose": "R6 Batch 1A: test whether predictor shift pattern is unique to K_eff",
  "method": "wild_cluster_bootstrap",
  "B": 9999,
  "weights": "rademacher",
  "clustering": "max_p_across_K_positions",
  "fdr_alpha": 0.05,
  "seed": 42,

  "SUMMARY": {
    "K3": {"kappa_div_fdr_sig": "8/12", "keff_fdr_sig": "3/12", "mean_rank_corr": 0.9893},
    "K5": {"kappa_div_fdr_sig": "7/12", "keff_fdr_sig": "7/12", "mean_rank_corr": 0.9867},
    "K7": {"kappa_div_fdr_sig": "6/12", "keff_fdr_sig": "8/12", "mean_rank_corr": 0.9855}
  },

  "predictor_shift_comparison": {
    "description": "Does significance increase from K=3 to K=5/7 for both predictors?",
    "kappa_diversity": {"K3": 8, "K5": 7, "K7": 6},
    "keff":            {"K3": 3, "K5": 7, "K7": 8}
  },

  "interpretation": "κ-diversity and K_eff are rank-correlated at ρ>0.985 but show OPPOSITE predictor shift patterns. κ-diversity significance DECREASES from K=3→7 (8→7→6/12) while K_eff INCREASES (3→7→8/12). This demonstrates that K_eff captures information-theoretic structure beyond simple agreement diversity — specifically, K_eff's MI-based formulation better captures the growing importance of judge independence at larger panel sizes."
}
